import java.util.*;

class Solution {
  private static final int MOD = 1_000_000_007;

  public int[] getFinalState(int[] nums, int k, int multiplier) {
    if (multiplier == 1) return nums;
    PriorityQueue<long[]> pq =
        new PriorityQueue<>(
            (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
    long maximum = 0;
    for (int i = 0; i < nums.length; i++) {
      pq.offer(new long[] {nums[i], i});
      maximum = Math.max(maximum, nums[i]);
    }
    while (k > 0 && pq.peek()[0] <= maximum / multiplier) {
      long[] cur = pq.poll();
      cur[0] *= multiplier;
      pq.offer(cur);
      k--;
    }
    int[] answer = new int[nums.length];
    int base = k / nums.length, extra = k % nums.length, rank = 0;
    while (!pq.isEmpty()) {
      long[] cur = pq.poll();
      long exponent = base + (rank < extra ? 1 : 0);
      answer[(int) cur[1]] = (int) ((cur[0] % MOD) * modPow(multiplier, exponent) % MOD);
      rank++;
    }
    return answer;
  }

  private long modPow(long base, long exponent) {
    long result = 1;
    while (exponent > 0) {
      if ((exponent & 1) != 0) result = result * base % MOD;
      base = base * base % MOD;
      exponent >>= 1;
    }
    return result;
  }
}
